 function keyInput(e){if(!enabled||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return false;if(e.code==='Escape'&&(run||paintPointer||!remote.hidden)){if(run)command(run,'exercise-stop');paintPointer=null;remote.hidden=true;e.preventDefault();return true;}if(get().paused&&!pc)return false;if(run&&e.code==='Space'){if(!e.repeat)command(run,'exercise-jump');e.preventDefault();return true;}if(!remote.hidden&&e.code.startsWith('Arrow')){if(!e.repeat)command(remoteTarget,'channel',{step:['ArrowLeft','ArrowDown'].includes(e.code)?-1:1});e.preventDefault();return true;}if(e.code==='KeyE'&&!e.repeat&&!cooking.handsOn){if(cooking.worldInteraction()){e.preventDefault();return true;}const t=pick();if(t&&interact(t,e.shiftKey)){e.preventDefault();return true;}}if(e.code==='KeyR'&&!e.repeat&&near&&['laundry','bath','microwave','trash'].includes(near.kind)){command(near,'start');e.preventDefault();return true;}if(e.code==='KeyF'&&!e.repeat&&near&&['laundry','bath','microwave','trash'].includes(near.kind)){command(near,'open');e.preventDefault();return true;}return false;}
